// Originally generated by `archegraph testgen`, then HAND-REPAIRED so it
// typechecks. Regenerating this file discards those repairs.

import { describe, expect, test } from 'bun:test';
import * as fc from 'fast-check';

import { create } from '@bufbuild/protobuf';
import { createEditorState } from '../src/state/create_editor_state';
import { Diagram, DiagramSchema } from '../../proto/src/gen/content_pb';
import { StyleEdit, StyleEditSchema, Stylesheet, StylesheetSchema } from '../../proto/src/gen/style_pb';

describe('testgen_state__createEditorState', () => {
    // REMOVED BY HAND: seven cases asserted `"acceptPending" in state` is
    // FALSE, and likewise for rejectPending and addComment. testgen runs
    // before the build, so it read a type surface on which this pillar's
    // methods did not exist yet and pinned their absence -- the opposite of
    // the spec. src/state/pending_review.test.ts covers the real behaviour.

    const makeChangedEdit = (id: string): StyleEdit => create(StyleEditSchema, { schemaVersion: 1, id, nodeChanges: [{ nodeId: id, changeType: 1 }], timestampMs: 0n, state: 0 });

    const makeDiagram = (): Diagram => create(DiagramSchema, { schemaVersion: 1, id: "diagram" });

    const makeEmptyEdit = (id: string): StyleEdit => create(StyleEditSchema, { schemaVersion: 1, id, timestampMs: 0n, state: 0 });

    const makeStylesheet = (pendingEdits: StyleEdit[]): Stylesheet => create(StylesheetSchema, { schemaVersion: 1, pendingEdits });

    // WHEN: The function is called with a diagram and stylesheet, creating state with those values, empty undo/redo logs, clean dirty state, and version zero.
    // THEN: It returns state exposing the supplied diagram and stylesheet with empty undo and redo logs, clean dirty state, and version zero.
    test('initial_state', () => {
        const diagram: Diagram = makeDiagram();
        const stylesheet: Stylesheet = makeStylesheet([]);
        const state = createEditorState(diagram, stylesheet);
        expect(state.diagram()).toBe(diagram);
        expect(state.stylesheet()).toBe(stylesheet);
        expect(state.canUndo()).toBe(false);
        expect(state.canRedo()).toBe(false);
        expect(state.dirty()).toBe(false);
        expect(state.version()).toBe(0);
    });

    test('apply_style_edit_with_changes', () => {
        fc.assert(
            fc.property(fc.string(), (value) => {
        const state = createEditorState(makeDiagram(), makeStylesheet([]));
        state.applyStyleEdit(makeChangedEdit(value));
        expect(state.canUndo()).toBe(true);
        expect(state.canRedo()).toBe(false);
        expect(state.dirty()).toBe(true);
        expect(state.version()).toBe(1);
            })
        );
    });

    // WHEN: applyStyleEdit receives an edit whose node, group, edge, and annotation change lists are all empty; it is a no-op.
    // THEN: It does nothing and leaves the stylesheet, history, dirty state, and version unchanged.
    test('apply_style_edit_empty', () => {
        const stylesheet: Stylesheet = makeStylesheet([]);
        const state = createEditorState(makeDiagram(), stylesheet);
        state.applyStyleEdit(makeEmptyEdit("empty"));
        expect(state.stylesheet()).toBe(stylesheet);
        expect(state.canUndo()).toBe(false);
        expect(state.canRedo()).toBe(false);
        expect(state.dirty()).toBe(false);
        expect(state.version()).toBe(0);
    });

    test('apply_style_edit_coalescing_key', () => {
        fc.assert(
            fc.property(fc.string(), (value) => {
        const state = createEditorState(makeDiagram(), makeStylesheet([]));
        state.applyStyleEdit(makeChangedEdit(value), value);
        expect(state.canUndo()).toBe(true);
        expect(state.version()).toBe(1);
            })
        );
    });

    // WHEN: undo is called when the undo log is empty; it is a no-op.
    // THEN: It does nothing when there is no undo history.
    test('undo_without_history', () => {
        const state = createEditorState(makeDiagram(), makeStylesheet([]));
        const before: Stylesheet = state.stylesheet();
        state.undo();
        expect(state.stylesheet()).toBe(before);
        expect(state.canUndo()).toBe(false);
        expect(state.canRedo()).toBe(false);
        expect(state.dirty()).toBe(false);
        expect(state.version()).toBe(0);
    });

    test('undo_with_history', () => {
        fc.assert(
            fc.property(fc.string(), (value) => {
        const state = createEditorState(makeDiagram(), makeStylesheet([]));
        state.applyStyleEdit(makeChangedEdit(value));
        const afterApply: Stylesheet = state.stylesheet();
        state.undo();
        expect(state.stylesheet()).not.toBe(afterApply);
        expect(state.canUndo()).toBe(false);
        expect(state.canRedo()).toBe(true);
        expect(state.dirty()).toBe(true);
        expect(state.version()).toBe(2);
            })
        );
    });

    // WHEN: redo is called when the redo log is empty; it is a no-op.
    // THEN: It does nothing when there is no redo history.
    test('redo_without_history', () => {
        const state = createEditorState(makeDiagram(), makeStylesheet([]));
        const before: Stylesheet = state.stylesheet();
        state.redo();
        expect(state.stylesheet()).toBe(before);
        expect(state.canUndo()).toBe(false);
        expect(state.canRedo()).toBe(false);
        expect(state.version()).toBe(0);
    });

    // WHEN: redo replays an entry produced by applyStyleEdit, whose pendingEditsAfter field is unset, leaving the pending-edits behavior otherwise unchanged.
    // THEN: It reapplies the ordinary edit without changing pendingEdits beyond the edit's normal behavior.
    test('redo_ordinary_entry', () => {
        const state = createEditorState(makeDiagram(), makeStylesheet([]));
        state.applyStyleEdit(makeChangedEdit("ordinary"));
        state.undo();
        const beforeRedo: Stylesheet = state.stylesheet();
        state.redo();
        expect(state.stylesheet()).not.toBe(beforeRedo);
        expect(state.canUndo()).toBe(true);
        expect(state.canRedo()).toBe(false);
        expect(state.stylesheet().pendingEdits).toEqual([]);
    });

    test.skip('redo_pending_transition_entry', () => {
        // test generation failed: generated body does not reference the bound value `value`
    });

    test('append_pending_edit', () => {
        fc.assert(
            fc.property(fc.string(), (value) => {
        const state = createEditorState(makeDiagram(), makeStylesheet([]));
        const edit: StyleEdit = makeEmptyEdit(value);
        state.appendPendingEdit(edit);
        // The helpers build messages as cast object literals, and
        // appendPendingEdit round-trips them through create(), which
        // normalizes and adds $typeName -- so a deep-equal against the
        // literal compares a message with a plain object. Assert the append.
        expect(state.stylesheet().pendingEdits).toHaveLength(1);
        expect(state.stylesheet().pendingEdits[0]?.id).toBe(edit.id);
        expect(state.version()).toBe(1);
        expect(state.canUndo()).toBe(false);
        expect(state.dirty()).toBe(false);
            })
        );
    });

    test('adopt_stylesheet', () => {
        fc.assert(
            fc.property(fc.string(), (value) => {
        const state = createEditorState(makeDiagram(), makeStylesheet([]));
        const next: Stylesheet = makeStylesheet([makeEmptyEdit(value)]);
        state.adoptStylesheet(next);
        expect(state.stylesheet()).toBe(next);
        expect(state.version()).toBe(1);
        expect(state.canUndo()).toBe(false);
        expect(state.dirty()).toBe(false);
            })
        );
    });

    test.skip('accept_missing_pending', () => {
        // test generation failed: generated body does not reference the bound value `value`
    });

    test.skip('reject_missing_pending', () => {
        // test generation failed: generated body does not reference the bound value `value`
    });

    test.skip('add_comment_missing_pending', () => {
        // test generation failed: generated body does not reference the bound value `value`
    });

});

